const uint8_t *retro_go_cjk_font_bitmap(uint32_t codepoint)
{
    size_t low = 0u;
    size_t high = sizeof(cjk_glyphs) / sizeof(cjk_glyphs[0]);

    if (codepoint > UINT16_MAX)
    {
        return NULL;
    }
    while (low < high)
    {
        size_t middle = low + (high - low) / 2u;
        uint16_t code = cjk_glyphs[middle].code;

        if (code < codepoint)
        {
            low = middle + 1u;
        }
        else
        {
            high = middle;
        }
    }
    return low < sizeof(cjk_glyphs) / sizeof(cjk_glyphs[0]) &&
                   cjk_glyphs[low].code == codepoint ?
               cjk_glyphs[low].bitmap : NULL;
}
